from pathlib import Path

source_path = Path(__file__).with_name("_pcna_app_source.py")
source = source_path.read_text(encoding="utf-8")

# Replace the legacy home-only sizing layer wholesale. The replacement uses normal
# document flow at every viewport width: no viewport-height math, no fixed card rows,
# no flex-to-fill behavior, and no vertical scroll locking.
start_marker = '''if page == "home":\n    st.markdown(\n        """\n<style>\n'''
end_marker = '''\n""",\n        unsafe_allow_html=True,\n    )\n\napproved_pcna_header(98 if page == "home" else 105)'''

start = source.index(start_marker)
end = source.index(end_marker, start) + len(end_marker)

home_layout = '''if page == "home":\n    st.markdown(\n        """\n<style>\n/* HOME — one responsive document-flow layout for desktop, tablet, and phone. */\n\nhtml,\nbody,\n[data-testid="stAppViewContainer"],\n[data-testid="stAppViewContainer"] > .main {\n  width: 100%;\n  min-height: 100%;\n  height: auto !important;\n  overflow-x: hidden !important;\n}\n\n/* Let Streamlit/browser scrolling remain natural. Never create a viewport-height shell. */\n[data-testid="stAppViewContainer"] > .main {\n  overflow-y: auto !important;\n  overscroll-behavior-y: auto;\n}\n\n.block-container {\n  width: 100% !important;\n  max-width: 1200px !important;\n  height: auto !important;\n  min-height: 0 !important;\n  box-sizing: border-box !important;\n  margin: 0 auto !important;\n  padding: calc(12px + env(safe-area-inset-top)) 20px calc(94px + env(safe-area-inset-bottom)) !important;\n  overflow: visible !important;\n}\n\n/* Remove Streamlit wrapper sizing from the home page. */\n.block-container > [data-testid="stVerticalBlock"],\n.block-container [data-testid="stVerticalBlock"],\n.block-container [data-testid="stElementContainer"] {\n  height: auto !important;\n  min-height: 0 !important;\n  overflow: visible !important;\n}\n\n.block-container > [data-testid="stVerticalBlock"] {\n  gap: 0 !important;\n}\n\n/* Logo: keep the approved asset, remove wasted wrapper space. */\n[data-testid="stImage"] {\n  margin: 0 0 4px !important;\n  padding: 0 !important;\n  overflow: visible !important;\n}\n[data-testid="stImage"] img {\n  display: block !important;\n  margin: 0 auto !important;\n  max-width: 100% !important;\n  height: auto !important;\n  object-fit: contain !important;\n}\n\n/* Hero is the only intentionally sized content block. Its parent stays in document flow. */\n.block-container [data-testid="stElementContainer"]:has(iframe[title="streamlit_component"]) {\n  height: auto !important;\n  min-height: 0 !important;\n  margin: 0 !important;\n  overflow: visible !important;\n}\niframe[title="streamlit_component"] {\n  display: block !important;\n  width: 100% !important;\n  height: 152px !important;\n  min-height: 0 !important;\n  margin: 0 !important;\n}\n\n.section-title {\n  font-size: 20px !important;\n  line-height: 1.08 !important;\n  margin: 7px 0 8px !important;\n}\n\n/* Card wrapper and grid grow from their content; they never consume 'remaining viewport' space. */\n.block-container [data-testid="stElementContainer"]:has(.action-grid),\n.block-container [data-testid="stElementContainer"]:has(.action-grid) > div {\n  height: auto !important;\n  min-height: 0 !important;\n  overflow: visible !important;\n}\n\n.action-grid {\n  display: grid !important;\n  grid-template-columns: repeat(4, minmax(0, 1fr)) !important;\n  grid-template-rows: none !important;\n  grid-auto-rows: 1fr;\n  align-items: stretch;\n  width: 100% !important;\n  height: auto !important;\n  min-height: 0 !important;\n  gap: 12px !important;\n  margin: 0 !important;\n  padding: 0 !important;\n  box-sizing: border-box !important;\n}\n\n.action-card {\n  display: flex !important;\n  flex-direction: column !important;\n  justify-content: flex-start !important;\n  width: 100% !important;\n  height: auto !important;\n  min-width: 0 !important;\n  min-height: 0 !important;\n  box-sizing: border-box !important;\n  padding: 14px !important;\n  border-radius: 15px !important;\n  overflow: visible !important;\n}\n.action-icon {\n  flex: 0 0 auto !important;\n  font-size: 22px !important;\n  line-height: 1 !important;\n  margin: 0 0 6px !important;\n}\n.action-title {\n  flex: 0 0 auto !important;\n  font-size: 16px !important;\n  line-height: 1.1 !important;\n  margin: 0 0 4px !important;\n}\n.action-copy {\n  font-size: 11.5px !important;\n  line-height: 1.22 !important;\n  margin: 0 !important;\n}\n\n/* Fixed navigation is allowed; page padding above guarantees the last row can clear it. */\n.bottom-nav {\n  height: 76px !important;\n  padding-bottom: max(7px, env(safe-area-inset-bottom)) !important;\n}\n\n@media (max-width: 900px) {\n  .block-container {\n    max-width: 620px !important;\n    padding-left: 15px !important;\n    padding-right: 15px !important;\n  }\n  .action-grid {\n    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;\n    gap: 10px !important;\n  }\n}\n\n@media (max-width: 430px) {\n  .block-container {\n    padding-top: calc(6px + env(safe-area-inset-top)) !important;\n    padding-left: 10px !important;\n    padding-right: 10px !important;\n    padding-bottom: calc(88px + env(safe-area-inset-bottom)) !important;\n  }\n  [data-testid="stImage"] {\n    margin-bottom: 2px !important;\n  }\n  iframe[title="streamlit_component"] {\n    height: 142px !important;\n  }\n  .section-title {\n    font-size: 19px !important;\n    margin: 5px 0 6px !important;\n  }\n  .action-grid {\n    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;\n    gap: 8px !important;\n  }\n  .action-card {\n    padding: 9px 10px !important;\n    border-radius: 14px !important;\n  }\n  .action-icon {\n    font-size: 20px !important;\n    margin-bottom: 4px !important;\n  }\n  .action-title {\n    font-size: 15.5px !important;\n    line-height: 1.08 !important;\n    margin-bottom: 3px !important;\n  }\n  .action-copy {\n    font-size: 11px !important;\n    line-height: 1.18 !important;\n  }\n}\n\n@media (max-width: 340px) {\n  .action-grid {\n    grid-template-columns: 1fr !important;\n  }\n}\n</style>\n""",\n        unsafe_allow_html=True,\n    )\n\napproved_pcna_header(98 if page == "home" else 105)'''

source = source[:start] + home_layout + source[end:]

exec(compile(source, str(source_path), "exec"), globals(), globals())
